-- Nexa Ponto - V11: inteligência do ponto no Nexa Brain.
-- Instala as regras do ponto na Central de Ações do Brain (module_code 'ponto').
-- Elas só detectam alguma coisa quando a empresa tem o módulo Ponto Eletrônico ligado; com o
-- módulo desligado ficam escondidas da empresa. Só roda se a Central de Ações já estiver instalada
-- (tabela brain_rules); senão não faz nada (aplicar de novo depois de instalar o Brain).

SET @nexa_sql := IF((SELECT COUNT(*) FROM information_schema.tables WHERE table_schema = DATABASE() AND table_name = 'brain_rules') = 0, 'SELECT 1',
  'INSERT INTO brain_rules (company_id,rule_code,module_code,name,description,default_severity,default_settings,action_url,recommendation,is_active,created_at,updated_at) VALUES
     (0,''PONTO_INCONSISTENCIA'',''ponto'',''Ponto com dias a tratar'',''Colaboradores com marcação faltando ou falta sem justificativa nos últimos dias (pela apuração do ponto).'',''warning'',''{"days":7,"max_alerts":30}'',''ponto_tratamento.php?so=1'',''Abra o tratamento do colaborador: inclua a marcação esquecida (com motivo) ou lance a ocorrência (atestado, folga, abono).'',1,NOW(),NOW()),
     (0,''PONTO_RISCO_CLT'',''ponto'',''Risco trabalhista na jornada'',''Intervalo menor que o mínimo (CLT art. 71), menos de 11h de descanso entre jornadas (art. 66) ou mais de 2h extras no dia (art. 59).'',''high'',''{"days":7,"max_alerts":30}'',''ponto_tratamento.php'',''Converse com o colaborador e o gestor da área e ajuste a escala; repetições aumentam o risco de passivo trabalhista.'',1,NOW(),NOW()),
     (0,''PONTO_PEDIDOS_PENDENTES'',''ponto'',''Pedidos do ponto aguardando o gestor'',''Pedidos de ajuste de marcação, justificativas/atestados e liberação de acesso esperando decisão.'',''high'',''{"hours":24}'',''ponto_ocorrencias.php'',''Aprove ou recuse os pedidos para manter a apuração e o fechamento em dia.'',1,NOW(),NOW()),
     (0,''PONTO_HORAS_EXTRAS_MES'',''ponto'',''Horas extras acima do limite no mês'',''Colaboradores que passaram do limite de horas extras definido para o mês.'',''warning'',''{"min_hours":10,"max_alerts":30}'',''ponto_fechamento.php'',''Reveja a escala ou o quadro da equipe; horas extras frequentes elevam o custo da folha.'',1,NOW(),NOW()),
     (0,''PONTO_BANCO_VENCER'',''ponto'',''Banco de horas perto de vencer'',''Créditos do banco de horas que vencem nos próximos dias (o que vence vai para pagamento).'',''warning'',''{"days_ahead":30,"max_alerts":30}'',''ponto_banco_horas.php'',''Programe folgas compensatórias antes do vencimento ou prepare o pagamento.'',1,NOW(),NOW()),
     (0,''PONTO_FECHAMENTO_PENDENTE'',''ponto'',''Mês do ponto sem fechamento'',''O mês anterior terminou e o fechamento do ponto ainda não foi feito.'',''warning'',''{"day_of_month":5}'',''ponto_fechamento.php'',''Trate as pendências e feche o mês para gerar a planilha da folha e atualizar o banco de horas.'',1,NOW(),NOW()),
     (0,''PONTO_ROSTO_A_CONFERIR'',''ponto'',''Marcações com rosto a conferir'',''Marcações feitas pelo Nexa sem o rosto conferido (rosto diferente, não encontrado ou sem foto).'',''high'',''{"days":7,"max_alerts":30}'',''ponto_marcacoes.php'',''Confira as fotos das marcações; rosto diferente do cadastro pode indicar ponto batido por outra pessoa.'',1,NOW(),NOW()),
     (0,''PONTO_USO_FORA_JORNADA'',''ponto'',''Uso do Nexa fora da jornada'',''Colaboradores que tentaram usar o Nexa fora do horário em vários dias (Acesso ao Nexa pelo ponto).'',''warning'',''{"days":7,"min_events":3,"max_alerts":30}'',''ponto_acesso.php'',''Verifique se há trabalho fora do horário sem registro de ponto (risco de horas extras não pagas).'',1,NOW(),NOW())
   ON DUPLICATE KEY UPDATE module_code=VALUES(module_code),name=VALUES(name),description=VALUES(description),default_severity=VALUES(default_severity),default_settings=VALUES(default_settings),action_url=VALUES(action_url),recommendation=VALUES(recommendation),is_active=1,updated_at=NOW()');
PREPARE nexa_stmt FROM @nexa_sql; EXECUTE nexa_stmt; DEALLOCATE PREPARE nexa_stmt;
